async def act(page):
    import re
    import asyncio

    # Small pause to allow transient UI to settle
    await asyncio.sleep(0.25)

    # 1) Try a simple keyboard-based dismissal first (Escape) which often closes popups.
    try:
        await page.keyboard.press("Escape")
        await asyncio.sleep(0.2)
    except Exception:
        pass

    # 2) Attempt to dismiss an accessible dialog if present using dialog -> button path.
    try:
        dialogs = page.get_by_role("dialog")
        if await dialogs.count() > 0:
            dlg = dialogs.nth(0)
            btns = dlg.get_by_role("button")
            btn_count = await btns.count()
            for i in range(btn_count):
                try:
                    # prefer aria-label/name, fall back to inner_text
                    name = await btns.nth(i).get_attribute("aria-label")
                except Exception:
                    name = None
                if not name:
                    try:
                        name = await btns.nth(i).inner_text()
                    except Exception:
                        name = ""
                if name and re.search(r"close|dismiss|cancel|×|x|✖|✕", name, re.I):
                    try:
                        await btns.nth(i).click()
                        await asyncio.sleep(0.2)
                        break
                    except Exception:
                        try:
                            await btns.nth(i).click(force=True)
                            await asyncio.sleep(0.2)
                            break
                        except Exception:
                            # continue to next candidate
                            pass
            else:
                # if loop did not break, as a best-effort click the first button
                if btn_count > 0:
                    try:
                        await btns.nth(0).click()
                        await asyncio.sleep(0.2)
                    except Exception:
                        pass
    except Exception:
        pass

    # 3) Try any global close-like button by accessible name as a fallback
    try:
        close_btns = page.get_by_role("button", name=re.compile(r"close", re.I))
        if await close_btns.count() > 0:
            try:
                await close_btns.nth(0).click()
                await asyncio.sleep(0.2)
            except Exception:
                try:
                    await close_btns.nth(0).click(force=True)
                    await asyncio.sleep(0.2)
                except Exception:
                    pass
    except Exception:
        pass

    # 4) Finally, attempt to click the first search-result link using the full role-path
    #    Path: main -> article (first) -> heading(level=2) -> link (first)
    try:
        main_locator = page.get_by_role("main")
        if await main_locator.count() == 0:
            return
        main = main_locator.nth(0)

        articles = main.get_by_role("article")
        if await articles.count() == 0:
            return
        first_article = articles.nth(0)

        heading_locator = first_article.get_by_role("heading", level=2)
        if await heading_locator.count() > 0:
            heading = heading_locator.nth(0)
            link_locator = heading.get_by_role("link")
            if await link_locator.count() > 0:
                try:
                    # navigation-causing click should be the last DOM interaction
                    await link_locator.nth(0).click()
                except Exception:
                    # If visibility/overlay still blocks, force the click as a last resort
                    await link_locator.nth(0).click(force=True)
                return

        # Fallback: click the first link inside the article
        article_links = first_article.get_by_role("link")
        if await article_links.count() > 0:
            try:
                await article_links.nth(0).click()
            except Exception:
                await article_links.nth(0).click(force=True)
            return
    except Exception:
        return

